func revertTarget(status string) string {
	switch status {
	case "Waiting":
		return "Inbound"
	case "Scheduled":
		return "Waiting"
	case "Loaded":
		return "Scheduled"
	case "Delivered":
		return "Loaded"
	case "Confirmed":
		return "Delivered"
	default:
		return ""
	}
}

func advanceTarget(status string) string {
	switch status {
	case "Inbound":
		return "Waiting"
	case "Waiting":
		return "Scheduled"
	case "Scheduled":
		return "Loaded"
	case "Loaded":
		return "Delivered"
	case "Delivered":
		return "Confirmed"
	default:
		return ""
	}
}

func advanceAction(status string) string {
	switch status {
	case "Inbound":
		return "ground"
	case "Waiting":
		return "schedule"
	case "Scheduled":
		return "load"
	case "Loaded":
		return "deliver"
	case "Delivered":
		return "confirm"
	default:
		return ""
	}
}

